def median(xs):
    if not xs:
        raise ValueError("List must not be empty")
    s = sorted(xs)
    if len(s) % 2 == 1:
        return s[len(s) // 2]
    else:
        return (s[len(s) // 2 - 1] + s[len(s) // 2]) / 2

