def format_row(name, value):
    return f"{name:<10}|{value:>8.2f}"

def sales_report(rows):
    out = [format_row(name, value) for name, value in rows]
    return "\n".join(out)

def cost_report(rows):
    lines = [format_row(name, value) for name, value in rows]
    return "\n".join(["COSTS"] + lines)

