import math

def is_prime(k):
    if k < 2:
        return False
    for d in range(2, int(math.sqrt(k)) + 1):
        if k % d == 0:
            return False
    return True


def primes_below(n):
    primes = []
    for k in range(2, n):
        if is_prime(k):
            primes.append(k)
    return primes

